package org.flippets.app;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** A searchable visual catalogue; IDs keep favorites stable across app updates. */
public final class GalleryDialog extends Dialog {
    final MainActivity owner;final UiTheme ui;final ArrayList<Integer> rows=new ArrayList<>();
    final Map<String,Bitmap> thumbs=new HashMap<>();final Adapter adapter=new Adapter();
    static final String[] MINI_IDS={"focus","water","words"};
    final TextView count;final LinearLayout tabs,sourceTabs;String category="Все типы",collection="Все",query="";
    int dp(float value){return Math.round(value*owner.getResources().getDisplayMetrics().density);}
    TextView label(String value,int size){return ui.label(value,size,false);}
    public GalleryDialog(MainActivity a){
        super(a,(a.getResources().getConfiguration().uiMode&android.content.res.Configuration.UI_MODE_NIGHT_MASK)==android.content.res.Configuration.UI_MODE_NIGHT_YES?android.R.style.Theme_Material_NoActionBar:android.R.style.Theme_Material_Light_NoActionBar);owner=a;ui=new UiTheme(a);
        LinearLayout root=new LinearLayout(a);root.setOrientation(1);root.setPadding(dp(20),dp(16),dp(20),dp(12));root.setBackgroundColor(ui.background);setContentView(root);
        root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets bars=android.os.Build.VERSION.SDK_INT>=30?i.getInsets(android.view.WindowInsets.Type.systemBars()|android.view.WindowInsets.Type.displayCutout()|android.view.WindowInsets.Type.ime()):android.graphics.Insets.of(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());v.setPadding(dp(20)+bars.left,dp(16)+bars.top,dp(20)+bars.right,dp(12)+bars.bottom);return i;});
        LinearLayout top=new LinearLayout(a);top.setGravity(Gravity.CENTER_VERTICAL);TextView title=label("Оформление",25);title.setTypeface(Typeface.create("sans-serif-medium",0));top.addView(title,new LinearLayout.LayoutParams(0,-2,1));Button close=ui.button("Готово",false,v->dismiss());top.addView(close);root.addView(top);
        EditText search=new EditText(a);search.setSingleLine(true);search.setHint("Найти оформление");search.setContentDescription("Поиск по названию оформления");search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);ui.field(search);LinearLayout.LayoutParams searchParams=ui.spaced();searchParams.topMargin=dp(16);root.addView(search,searchParams);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){query=s.toString();filter();}public void afterTextChanged(Editable e){}});
        HorizontalScrollView sources=new HorizontalScrollView(a);sources.setHorizontalScrollBarEnabled(false);sourceTabs=new LinearLayout(a);sources.addView(sourceTabs);root.addView(sources,ui.spaced());
        for(String name:new String[]{"Все","17 Pro","18 Pro","Свои","Архив Xiaomi"}){Button b=ui.button(name,false,v->{collection=name;filter();refreshTabs();});ui.chip(b,name.equals(collection));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.rightMargin=dp(8);sourceTabs.addView(b,p);}
        HorizontalScrollView scroll=new HorizontalScrollView(a);scroll.setHorizontalScrollBarEnabled(false);tabs=new LinearLayout(a);scroll.addView(tabs);root.addView(scroll,ui.spaced());
        for(String name:new String[]{"Все типы","Избранное","Питомцы","Часы и виджеты","Фото и текст","Мини-приложения","Видео","Эффекты"}){Button b=ui.button(name,false,v->{category=name;filter();refreshTabs();});ui.chip(b,name.equals(category));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-2,-2);p.rightMargin=dp(8);tabs.addView(b,p);}
        count=ui.label("",13,true);count.setPadding(0,dp(12),0,dp(12));count.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);root.addView(count);
        GridView grid=new GridView(a){protected void onSizeChanged(int w,int h,int oldw,int oldh){super.onSizeChanged(w,h,oldw,oldh);float scale=a.getResources().getConfiguration().fontScale;setNumColumns(Math.max(1,Math.min(3,w/(dp(148*Math.max(1,scale))+dp(12)))));}};
        grid.setNumColumns(2);grid.setHorizontalSpacing(dp(12));grid.setVerticalSpacing(dp(12));grid.setClipToPadding(false);grid.setPadding(0,0,0,dp(12));grid.setAdapter(adapter);root.addView(grid,new LinearLayout.LayoutParams(-1,0,1));
        root.setFocusableInTouchMode(true);root.requestFocus();filter();setOnDismissListener(v->{for(Bitmap image:thumbs.values())if(image!=null)image.recycle();thumbs.clear();if(!owner.isFinishing()&&!owner.isDestroyed())owner.preview.start();});
    }
    void refreshTabs(){for(LinearLayout row:new LinearLayout[]{sourceTabs,tabs})for(int i=0;i<row.getChildCount();i++){Button b=(Button)row.getChildAt(i);ui.chip(b,b.getText().toString().equals(row==sourceTabs?collection:category));}}
    public void show(){owner.preview.stop();super.show();getWindow().setLayout(-1,-1);ui.window(getWindow());getWindow().setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);}
    static String group(JSONObject pet){String type=pet.optString("renderer"),kind=pet.optString("kind"),name=pet.optString("name");if(kind.equals("composition"))return type.equals("analog")||type.equals("dragon")||type.equals("stretch")||type.equals("steps")?"Часы и виджеты":"Фото и текст";if(kind.equals("video"))return "Видео";if(pet.optString("renderRole").equals("effect")||name.equals("Flowing glitter")||name.equals("Системные эффекты")||name.equals("Butterfly carp"))return "Эффекты";return "Питомцы";}
    static String collection(JSONObject pet){String renderer=pet.optString("renderer");if(Arrays.asList("photo","signature","paper","calendar").contains(renderer))return "Свои";String source=pet.optString("source");if(source.contains("18 Pro"))return "18 Pro";if(source.contains("17 Pro"))return "17 Pro";return "Архив Xiaomi";}
    Set<String> favorites(){return new HashSet<>(owner.getSharedPreferences(Pets.PREFS,0).getStringSet("favorites",Collections.emptySet()));}
    boolean matches(String id,String name,String source,String type,Set<String> stars){String search=query.trim().toLowerCase(Locale.ROOT);return (name+" "+source+" "+type).toLowerCase(Locale.ROOT).contains(search)&&(collection.equals("Все")||collection.equals(source))&&(category.equals("Все типы")||category.equals("Избранное")&&stars.contains(id)||category.equals(type));}
    void filter(){rows.clear();Set<String> stars=favorites();JSONArray cat=Pets.catalog(owner);for(int i=0;i<cat.length();i++){JSONObject p=cat.optJSONObject(i);if(matches(p.optString("id"),p.optString("name"),collection(p),group(p),stars))rows.add(i);}for(int i=0;i<MINI_IDS.length;i++)if(matches("mini-"+MINI_IDS[i],MiniAppStore.title(MINI_IDS[i]),"18 Pro","Мини-приложения",stars))rows.add(-1-i);String detail=collection.equals("Свои")?"Свои · шаблоны для фото и текста":collection;count.setText(rows.isEmpty()?"Ничего не найдено · измени категорию или поиск":"Найдено: "+rows.size()+" · "+detail);adapter.notifyDataSetChanged();}
    Bitmap thumb(String id){if(!thumbs.containsKey(id)){Bitmap b=null;try(java.io.InputStream s=owner.getAssets().open("thumbs/"+id+".webp")){b=BitmapFactory.decodeStream(s);}catch(Exception ignored){}thumbs.put(id,b);}return thumbs.get(id);}
    class Adapter extends BaseAdapter {
        public int getCount(){return rows.size();}public Object getItem(int position){return rows.get(position);}public long getItemId(int position){return rows.get(position);}
        public View getView(int position,View convert,ViewGroup parent){int index=rows.get(position);boolean mini=index<0;String app=mini?MINI_IDS[-1-index]:"";JSONObject pet=mini?new JSONObject():Pets.catalog(owner).optJSONObject(index);String id=mini?"mini-"+app:pet.optString("id"),title=mini?MiniAppStore.title(app):pet.optString("name"),source=mini?"18 Pro":collection(pet),type=mini?"Мини-приложения":group(pet);boolean selected=mini?MiniAppStore.selected(owner).equals(app):!MiniAppStore.valid(MiniAppStore.selected(owner))&&Pets.current(owner).optString("id").equals(id);LinearLayout card=new LinearLayout(owner);card.setOrientation(1);card.setPadding(dp(12),dp(12),dp(12),dp(8));GradientDrawable bg=ui.shape(ui.surface,24);if(selected)bg.setStroke(dp(2),ui.primary);card.setBackground(bg);card.setClipToOutline(true);
            if(mini){TextView image=label(app.equals("focus")?"25:00":app.equals("water")?"8 стаканов":"Aa",30);image.setTypeface(Typeface.create("sans-serif-medium",0));image.setGravity(Gravity.CENTER);ui.card(image,ui.container,18);image.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);card.addView(image,new LinearLayout.LayoutParams(-1,dp(145)));}else{ImageView image=new ImageView(owner);image.setImageBitmap(thumb(id));image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);ui.card(image,ui.container,18);card.addView(image,new LinearLayout.LayoutParams(-1,dp(145)));}
            TextView name=label(title,16);name.setTypeface(Typeface.create("sans-serif-medium",0));name.setPadding(0,dp(12),0,dp(4));name.setMaxLines(2);name.setEllipsize(TextUtils.TruncateAt.END);name.setMinHeight(dp(54));card.addView(name);
            TextView provenance=ui.label(source+" · "+type,11,true);provenance.setMaxLines(2);card.addView(provenance);
            LinearLayout foot=new LinearLayout(owner);foot.setGravity(Gravity.CENTER_VERTICAL);TextView kind=ui.label(selected?"Выбрано":mini?"Посмотреть":"Выбрать",12,true);if(selected)kind.setTextColor(ui.primary);foot.addView(kind,new LinearLayout.LayoutParams(0,-2,1));Button star=ui.button("",false,null);boolean favorite=favorites().contains(id);star.setText(favorite?"★":"☆");star.setTextSize(24);star.setPadding(0,0,0,0);star.setMinHeight(dp(48));star.setMinimumHeight(dp(48));star.setMinWidth(0);star.setMinimumWidth(0);star.setContentDescription((favorite?"Убрать из избранного: ":"В избранное: ")+title);foot.addView(star,new LinearLayout.LayoutParams(dp(48),dp(48)));card.addView(foot);
            star.setOnClickListener(v->{Set<String> set=favorites();if(!set.remove(id))set.add(id);owner.getSharedPreferences(Pets.PREFS,0).edit().putStringSet("favorites",set).apply();filter();});card.setContentDescription((selected?"Выбрано. ":"Выбрать ")+title+". "+source+". "+type);card.setFocusable(true);card.setOnClickListener(v->{if(mini){dismiss();owner.miniDialog=MiniAppsDialog.show(owner,app);}else{owner.select(index);dismiss();}});return card;
        }
    }
}
